import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.1Y430-yj.js";const h=JSON.parse('{"title":"Building the Task Board","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"任务板建设","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=TLHwGPUCRgA2PWPTgu1GGk","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-TLHwGPUCRgA2PWPTgu1GGk.md","filePath":"logistics/src/page-TLHwGPUCRgA2PWPTgu1GGk.md","lastUpdated":null}'),o={name:"logistics/src/page-TLHwGPUCRgA2PWPTgu1GGk.md"};function n(r,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="任务板建设" aria-hidden="true"></span><h1 id="building-the-task-board" tabindex="-1">Building the Task Board <a class="header-anchor" href="#building-the-task-board" aria-label="Permalink to &quot;Building the Task Board&quot;">​</a></h1><blockquote><p>Source page ID: <code>TLHwGPUCRgA2PWPTgu1GGk</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=TLHwGPUCRgA2PWPTgu1GGk" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><a href="./page-BsvydVIho4LYEe3x3bNGPf">JMY&#39;s Website Development</a> · <a href="./page-rrWHMKISS4qKgjn1ObgLkv">Tencent Docs Defect List</a> · <a href="./page-nH85HSQtBsJSwkT5SgzV5P">The Great Task-Board Migration</a></p><p>In the early-hours discussion on 2026/5/10, we realized the current task board relies heavily on manual recording and lacks a shared way to describe completion. The pre-board task “Implementing a Perfectly Uniform Rational-Output Device,” for instance, produced many results but cannot be recorded simply chronologically because it has several approaches. Likewise, no one knows when “Damping Theory” will receive its final summary. We solicit suggestions to improve the board: it should be both a recorder of topic-centered “tasks” and a way for anyone to join group discussions quickly or look up results.</p><p>Most tasks plainly have multiple approaches running in parallel: simultaneous, somewhat independent, and potentially mutually inspiring. Their results, however, progress serially over time. Most remaining tasks consist of dependent parts such as summarization and video production, which can often merge. Progression-planning tasks similarly include pre-update preparation—preview-derived recipes and summaries of soon-unlocking content—and post-update work—total mineral supply, production calculations, blueprint construction, and videos. Staged updates such as [“At the Wake of Spring”] repeat these stages. The main body should therefore combine serial and parallel organization, and be the main part maintained.</p><p><s>To help newcomers join and established members catch up, create a section collecting every kind of result: a small structure and possible uses, an experiment and implications, a coherent theory and applications, or an idea and missing pieces. Results should be periodically selected during a task, not summarized only after completion. Compared with the main task board, these entries should be more atomic, mentioning only where they are cited.</s></p><p><s>Daily summaries are excellent but labor-intensive. AI hallucinates when summarizing too much daily text, requiring manual checking, with no current solution. Summaries should align with board tasks, avoiding chronological logs that add unrelated content without an associated task request. Update the board periodically from results rather than maintaining daily summaries as a separate board section.</s></p><p><s>“Completed” should not be a separate section: the label is too broad. Issues unlikely to be discussed again—current approaches exhausted, remaining research abandoned, video publication complete, etc.—need finer completion states. Which states to use needs further thought.</s></p><p><s>The update record should note task creation/renaming but omit detailed reasons, giving at most one sentence. Reasons belong inside tasks, along with who proposed each part. Record discussion participants and contributions as time permits. Results should similarly include participants and references; this optional maintenance should mainly rely on participants signing and claiming their contributions.</s></p><p>Add references and introductions to outside results. Material published online beyond the group is worth consulting; this remains to be added.</p><p>Revise classification: some tasks do not fit simply into one of the three categories.</p><p>Some tasks may never end; determine whether to add a long-term task category.</p><p><s>Add page prerequisites and follow-ups, such as “this document&#39;s terminology and concepts come from xx” and “applications of this document&#39;s results” (kokobird). Appropriate use of references suffices; adjust while writing (jnk).</s></p></div>',1)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
